package com.evolution.analysis.polyglot;

import java.io.*;
import java.util.*;
import com.evolution.analysis.contract.common.*;
import com.evolution.analysis.contract.serialization.CanonicalJson;
import com.evolution.analysis.execution.EvidenceVerifier;
import java.security.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SemanticAnswerLedgerTest {
    @Test void contradictoryRelationOwnersAndKindsCannotCollapseToTheSameAnswer()throws Exception{
        var authority=new Authority();var f=authority.fixture;var baseline=authority.answer("same-call");var outputs=new ArrayList<SemanticTables.Table>();var claims=new HashMap<SemanticTables.Table,Map<String,EvidenceVerifier.VerifiedClaim>>();
        for(var meaning:List.of(List.of("ChildA","EXTENDS"),List.of("ChildB","EXTENDS"),List.of("ChildA","IMPLEMENTS"))){var rows=new ArrayList<SemanticTables.Row>();try(var reader=f.tables.open(baseline,()->false)){SemanticTables.Row row;while((row=reader.next())!=null){var fields=new TreeMap<>(row.fields());if(row.key().equals("A05")){fields.put("status","RESOLVED");fields.put("targets",List.of(ContentDigest.sha256Utf8("Base").value()));fields.put("owner",ContentDigest.sha256Utf8(meaning.getFirst()).value());fields.put("relation",meaning.getLast());}rows.add(new SemanticTables.Row(row.kind(),row.key(),row.scope(),fields));}}var output=f.tables.write(SemanticTables.Kind.OBSERVATION,rows.iterator(),()->false);outputs.add(output);claims.put(output,authority.prove(output));}
        var ledger=new SemanticAnswerLedger(f.content,f.tables);for(int other:List.of(1,2)){var history=ledger.append(f.request,outputs.getFirst(),Optional.empty(),()->false);history=ledger.append(f.request,outputs.get(other),Optional.of(history),()->false);var result=ledger.fold(f.request,history,(r,o)->claims.get(o),Set.of(),f.request::policy,g->{},()->false);assertEquals(1,result.counts().get("CONFLICTED"));assertFalse(result.answersComplete());}
    }
    @Test void producerAnswersStayNarrowedAndAnEmptyLaterOutputCannotEraseQuestions()throws Exception{
        var f=new SemanticReconcilerTest.Fixture();var ledger=new SemanticAnswerLedger(f.content,f.tables);var history=ledger.append(f.request,fixtureOutput(f),Optional.empty(),()->false);var empty=f.tables.write(SemanticTables.Kind.OBSERVATION,Collections.emptyIterator(),()->false);history=ledger.append(f.request,empty,Optional.of(history),()->false);var gaps=new ArrayList<com.evolution.analysis.evidence.CapabilityGapRecord>();var result=ledger.fold(f.request,history,(r,t)->Map.of(),Set.of(),f.request::policy,gaps::add,()->false);
        assertEquals(12,result.questions());assertEquals(12,result.counts().get("NARROWED"));assertFalse(result.answersComplete());assertEquals(12,gaps.size());assertEquals(2,history.revisions().rows());
        assertThrows(IOException.class,()->ledger.fold(f.request,result.history(),(r,t)->Map.of(),Set.of(),()->com.evolution.analysis.contract.common.ContentDigest.sha256Utf8("revoked policy"),g->{},()->false));
    }
    static SemanticTables.Table fixtureOutput(SemanticReconcilerTest.Fixture fixture)throws IOException{return fixture.emissions(fixture.requirements);}
    /** Ephemeral authored keys exercise proof handling, never production registration. */
    static final class Authority {
        final SemanticReconcilerTest.Fixture fixture=new SemanticReconcilerTest.Fixture();final KeyPair controller,validator;final List<EvidenceVerifier.Method> methods;final EvidenceVerifier verifier;
        Authority()throws Exception{this(true);}
        Authority(boolean allClosed)throws Exception{
            var generator=KeyPairGenerator.getInstance("Ed25519");controller=generator.generateKeyPair();validator=generator.generateKeyPair();var tool=fixture.request.tool();methods=List.of(new EvidenceVerifier.Method(new VersionedIdentifier("authored.ledger-census","v1"),new VersionedIdentifier("polyglot.census","m8.4-v1"),tool,List.of("INDEPENDENT_CENSUS","DOCUMENT_MEMBERSHIP","CATEGORY_CLOSURE")),new EvidenceVerifier.Method(new VersionedIdentifier("authored.ledger-observations","v1"),new VersionedIdentifier("polyglot.observations","m8.4-v1"),tool,allClosed?List.of("CALLER_TARGET_ORIGIN","SOURCE_COORDINATES","APPLICABILITY_VALIDATED","ALL_OBSERVATIONS_CLOSED"):List.of("CALLER_TARGET_ORIGIN","SOURCE_COORDINATES","APPLICABILITY_VALIDATED")));verifier=new EvidenceVerifier(Map.of("controller",controller.getPublic()),Map.of("validator",validator.getPublic()),methods);var r=fixture.request;fixture.request=new LanguageSemanticRequest(r.context(),r.inventory(),r.root(),r.module(),r.sourceSet(),r.variant(),r.language(),r.dialect(),r.documents(),r.census(),r.resolution(),r.provider(),r.tool(),verifier.policyIdentity(),r.workPolicy());
        }
        SemanticTables.Table answer(String target)throws IOException{
            var rows=new ArrayList<SemanticTables.Row>();for(var question:fixture.requirements){boolean call=question.key().equals("A06");rows.add(new SemanticTables.Row(SemanticTables.Kind.OBSERVATION,question.key(),question.scope(),Map.of("obligation",question.identity().value(),"status",call||Set.of("A01","A11","A12").contains(question.key())?"RESOLVED":"NOT_APPLICABLE","targets",call?List.of(ContentDigest.sha256Utf8(target).value()):List.of())));}return fixture.tables.write(SemanticTables.Kind.OBSERVATION,rows.iterator(),()->false);
        }
        Map<String,EvidenceVerifier.VerifiedClaim> prove(SemanticTables.Table output)throws Exception{
            var request=fixture.request;var claim=fixture.content.text(CanonicalJson.write(SemanticReconciler.proofPayload(request,output)));var proofs=new TreeMap<String,EvidenceVerifier.VerifiedClaim>();for(var method:methods){var expected=new EvidenceVerifier.Expected(ContentDigest.sha256Utf8("launch"),ContentDigest.sha256Utf8("profile"),1,request.scope(),request.inputClosure(),claim,method.method(),method.predicate(),method.tool());var receipt=new EvidenceVerifier.Receipt("execution-protected-receipt:m8.4-v1","authored-control",1,expected.launch(),expected.profile(),ContentDigest.sha256Utf8("manifest"),ContentDigest.sha256Utf8("materials"),ContentDigest.sha256Utf8("termination"));var attestation=new EvidenceVerifier.Attestation("execution-protected-attestation:m8.4-v1",receipt.identity(),claim.digest(),request.scope(),request.inputClosure(),method.tool(),method.method(),method.predicate(),method.requiredChecks(),true);proofs.put(method.predicate().id().substring("polyglot.".length()),verifier.verifyAccepted(expected,receipt,sign("controller",receipt,controller.getPrivate()),attestation,sign("validator",attestation,validator.getPrivate()),fixture.content).orElseThrow());}return proofs;
        }
        static EvidenceVerifier.SignatureEnvelope sign(String id,Object payload,PrivateKey key)throws Exception{var signer=Signature.getInstance("Ed25519");signer.initSign(key);signer.update(CanonicalJson.write(Map.of("keyId",id,"payload",payload)).getBytes(java.nio.charset.StandardCharsets.UTF_8));return new EvidenceVerifier.SignatureEnvelope(id,Base64.getEncoder().encodeToString(signer.sign()));}
    }
    @Test void contradictoryQualifiedAnswersDoNotDependOnArrivalAndRevocationReopensEvidence()throws Exception{
        var authority=new Authority();var f=authority.fixture;var ledger=new SemanticAnswerLedger(f.content,f.tables);var first=authority.answer("first");var second=authority.answer("second");var firstProofs=authority.prove(first);var secondProofs=authority.prove(second);SemanticAnswerLedger.Proofs proofs=(r,t)->t.equals(first)?firstProofs:secondProofs;
        var one=ledger.append(f.request,first,Optional.empty(),()->false);assertTrue(ledger.fold(f.request,one,proofs,Set.of(),f.request::policy,g->{},()->false).answersComplete());var forward=ledger.append(f.request,second,Optional.of(one),()->false);var reverse=ledger.append(f.request,first,Optional.of(ledger.append(f.request,second,Optional.empty(),()->false)),()->false);var left=ledger.fold(f.request,forward,proofs,Set.of(),f.request::policy,g->{},()->false);var right=ledger.fold(f.request,reverse,proofs,Set.of(),f.request::policy,g->{},()->false);
        assertFalse(left.answersComplete());assertEquals(1,left.counts().get("CONFLICTED"));assertEquals(1,left.conflicts().rows());assertEquals(left.current(),right.current());assertEquals(left.conflicts(),right.conflicts());assertNotEquals(forward.identity(),reverse.identity());
        var narrowed=ledger.fold(f.request,forward,proofs,Set.of(secondProofs.get("observations").identity()),f.request::policy,g->{},()->false);assertTrue(narrowed.answersComplete());assertEquals(0,narrowed.conflicts().rows());assertTrue(f.content.verify(left.conflicts().content()));var reopened=ledger.fold(f.request,forward,proofs,Set.of(firstProofs.get("observations").identity(),secondProofs.get("observations").identity()),f.request::policy,g->{},()->false);assertEquals(12,reopened.counts().get("REOPENED"));assertFalse(reopened.answersComplete());
    }
    @Test void lostPreviouslyValidatedBytesAndForgedHistoryNeverRestoreSavedAcceptance()throws Exception{
        var authority=new Authority();var f=authority.fixture;var ledger=new SemanticAnswerLedger(f.content,f.tables);var output=authority.answer("first");var proofs=authority.prove(output);var history=ledger.append(f.request,output,Optional.empty(),()->false);f.content.blobs.remove(output.content().digest());var gaps=new ArrayList<com.evolution.analysis.evidence.CapabilityGapRecord>();var lost=ledger.fold(f.request,history,(r,t)->proofs,Set.of(),f.request::policy,gaps::add,()->false);assertEquals(1,lost.unavailableRevisions());assertEquals(12,lost.counts().get("REOPENED"));assertFalse(lost.answersComplete());assertEquals(13,gaps.size());
        assertThrows(IOException.class,()->ledger.fold(f.request,history,(r,t)->proofs,Set.of(),f.request::policy,g->{},()->true));assertEquals(1,history.revisions().rows());assertThrows(IllegalArgumentException.class,()->new SemanticAnswerLedger.History(history.scope(),lost.current()));
        SemanticTables.Row row;try(var reader=f.tables.open(history.revisions(),()->false)){row=reader.next();}var fields=new TreeMap<>(row.fields());fields.put("complete",true);var forged=f.tables.write(SemanticTables.Kind.REVISION,List.of(new SemanticTables.Row(SemanticTables.Kind.REVISION,row.key(),row.scope(),fields)).iterator(),()->false);assertThrows(IOException.class,()->ledger.fold(f.request,new SemanticAnswerLedger.History(history.scope(),forged),(r,t)->proofs,Set.of(),f.request::policy,g->{},()->false));
    }
    @Test void revokingAnUncertainObservationCannotPretendItPreviouslyClosedTheQuestion()throws Exception{
        var authority=new Authority(false);var f=authority.fixture;var complete=authority.answer("target");var rows=new ArrayList<SemanticTables.Row>();try(var reader=f.tables.open(complete,()->false)){SemanticTables.Row row;while((row=reader.next())!=null){var fields=new TreeMap<>(row.fields());if(row.key().equals("A06")){fields.put("status","UNRESOLVED");fields.put("targets",List.of());fields.put("reason","NATIVE_BINDING_UNAVAILABLE");}rows.add(new SemanticTables.Row(row.kind(),row.key(),row.scope(),fields));}}var uncertain=f.tables.write(SemanticTables.Kind.OBSERVATION,rows.iterator(),()->false);var proofs=authority.prove(uncertain);var ledger=new SemanticAnswerLedger(f.content,f.tables);var history=ledger.append(f.request,uncertain,Optional.empty(),()->false);var before=ledger.fold(f.request,history,(r,t)->proofs,Set.of(),f.request::policy,g->{},()->false);assertEquals(1,before.counts().get("NARROWED"));var revoked=ledger.fold(f.request,history,(r,t)->proofs,Set.of(proofs.get("observations").identity()),f.request::policy,g->{},()->false);assertEquals(1,revoked.counts().get("NARROWED"));assertEquals(11,revoked.counts().get("REOPENED"));assertFalse(revoked.answersComplete());
    }
}
